import{_ as e,o as i,c as t,a2 as s}from"./chunks/framework.OLpNgP4A.js";const m=JSON.parse('{"title":"Data Analysis & SQL Proficiency Guide","description":"Comprehensive framework for mastering advanced SQL recipes, window functions, CTEs, exploratory data analysis, and data manipulation workflows based on SQL Cookbook and Python for Data Analysis","frontmatter":{"title":"Data Analysis & SQL Proficiency Guide","description":"Comprehensive framework for mastering advanced SQL recipes, window functions, CTEs, exploratory data analysis, and data manipulation workflows based on SQL Cookbook and Python for Data Analysis"},"headers":[],"relativePath":"data-engineering/sql-recipes.md","filePath":"data-engineering/sql-recipes.md","lastUpdated":1789221836000}'),n={name:"data-engineering/sql-recipes.md"};function r(o,a,d,l,c,p){return i(),t("div",null,[...a[0]||(a[0]=[s('<h1 id="data-analysis-sql-proficiency" tabindex="-1">Data Analysis &amp; SQL Proficiency <a class="header-anchor" href="#data-analysis-sql-proficiency" aria-label="Permalink to &quot;Data Analysis &amp; SQL Proficiency&quot;">​</a></h1><p>Raw data sitting in storage provides zero value until it is queried, cleaned, transformed, and analyzed. Mastering both relational manipulation and programmatic data wrangling is what separates standard developers from elite data engineers and analysts.</p><p>Below is the definitive master guide synthesized from Anthony Molinaro’s <strong>SQL Cookbook</strong> and Wes McKinney’s <strong>Python for Data Analysis</strong>.</p><hr><h2 id="part-i-advanced-sql-patterns-window-functions" tabindex="-1">Part I: Advanced SQL Patterns &amp; Window Functions <a class="header-anchor" href="#part-i-advanced-sql-patterns-window-functions" aria-label="Permalink to &quot;Part I: Advanced SQL Patterns &amp; Window Functions&quot;">​</a></h2><p>Complex aggregations and windowing allow you to look across multiple rows without collapsing your dataset, solving intricate analytical reporting patterns cleanly (<em>SQL Cookbook, Chapters 4 &amp; 5</em>).</p><div class="testing-stack"><div class="testing-card ctci-card-1"><div class="card-header"><h3>Window Functions</h3><span class="tagline">Partitioning &amp; Ranking</span></div><div class="card-body"><p><strong>Core Concept:</strong> Compute aggregates across sets of table rows that are somehow related to the current row without grouping the whole result set.</p><p><strong>Example Query:</strong></p><p><code>SELECT employee_id, department, salary, RANK() OVER (PARTITION BY department ORDER BY salary DESC) as dept_rank FROM employees;</code></p></div></div><div class="testing-card ctci-card-1"><div class="card-header"><h3>Lag &amp; Lead Analysis</h3><span class="tagline">Row-to-Row Comparison</span></div><div class="card-body"><p><strong>Time-Series Deltas:</strong> Access data from previous or subsequent rows to calculate period-over-period growth or transaction gaps.</p><p><strong>Example Query:</strong></p><p><code>SELECT transaction_date, amount, LAG(amount, 1) OVER (ORDER BY transaction_date) as prev_amount FROM transactions;</code></p></div></div></div><hr><h2 id="part-ii-complex-aggregations-recursive-queries" tabindex="-1">Part II: Complex Aggregations &amp; Recursive Queries <a class="header-anchor" href="#part-ii-complex-aggregations-recursive-queries" aria-label="Permalink to &quot;Part II: Complex Aggregations &amp; Recursive Queries&quot;">​</a></h2><p>Handling hierarchical data structures and conditional grouping patterns without writing convoluted loops (<em>SQL Cookbook, Chapters 2 &amp; 9</em>).</p><div class="testing-stack"><div class="testing-card ctci-card-2"><div class="card-header"><h3>Common Table Expressions (CTEs)</h3><span class="tagline">Modular Querying</span></div><div class="card-body"><p><strong>Readability:</strong> Break down massive, multi-join queries into clean, named temporary result sets using the `WITH` clause.</p></div></div><div class="testing-card ctci-card-2"><div class="card-header"><h3>Recursive CTEs</h3><span class="tagline">Hierarchical Trees</span></div><div class="card-body"><p><strong>Graph Traversals:</strong> Query organizational charts, bill of materials, or multi-level category trees by combining an anchor member with a recursive member.</p><p><strong>Example Query:</strong></p><p><code>WITH RECURSIVE subordinates AS (SELECT id, manager_id, name FROM employees WHERE id = 1 UNION ALL SELECT e.id, e.manager_id, e.name FROM employees e JOIN subordinates s ON e.manager_id = s.id) SELECT * FROM subordinates;</code></p></div></div></div><hr><h2 id="part-iii-exploratory-data-analysis-eda-data-cleaning-with-python" tabindex="-1">Part III: Exploratory Data Analysis (EDA) &amp; Data Cleaning with Python <a class="header-anchor" href="#part-iii-exploratory-data-analysis-eda-data-cleaning-with-python" aria-label="Permalink to &quot;Part III: Exploratory Data Analysis (EDA) &amp; Data Cleaning with Python&quot;">​</a></h2><p>Programmatic data manipulation requires robust cleaning workflows to handle missing values, formatting discrepancies, and type mismatches (<em>Python for Data Analysis, Chapters 5, 7, &amp; 9</em>).</p><div class="testing-stack"><div class="testing-card ctci-card-3"><div class="card-header"><h3>Handling Missing Data</h3><span class="tagline">Data Sanitization</span></div><div class="card-body"><p><strong>Null Identification &amp; Imputation:</strong> Identify missing values via `df.isnull()` and handle them systematically using `.dropna()` or `.fillna()`, avoiding silent statistical distortion.</p><p><strong>Code Snippet:</strong></p><p><code>import pandas as pd<br>df[&#39;salary&#39;] = df[&#39;salary&#39;].fillna(df[&#39;salary&#39;].median())</code></p></div></div><div class="testing-card ctci-card-3"><div class="card-header"><h3>Data Transformation &amp; Casting</h3><span class="tagline">Type Safety</span></div><div class="card-body"><p><strong>String &amp; DateTime Parsing:</strong> Clean messy string formatting and convert object columns into structured datetime or categorical types for memory efficiency.</p><p><strong>Code Snippet:</strong></p><p><code>df[&#39;date&#39;] = pd.to_datetime(df[&#39;date&#39;], errors=&#39;coerce&#39;)<br>df[&#39;category&#39;] = df[&#39;category&#39;].astype(&#39;category&#39;)</code></p></div></div></div><hr><h2 id="part-iv-advanced-data-manipulation-aggregation-in-pandas" tabindex="-1">Part IV: Advanced Data Manipulation &amp; Aggregation in Pandas <a class="header-anchor" href="#part-iv-advanced-data-manipulation-aggregation-in-pandas" aria-label="Permalink to &quot;Part IV: Advanced Data Manipulation &amp; Aggregation in Pandas&quot;">​</a></h2><p>Grouping, pivoting, and merging disparate datasets to produce analytical business metrics (<em>Python for Data Analysis, Chapters 8 &amp; 10</em>).</p><div class="testing-stack"><div class="testing-card ctci-card-4"><div class="card-header"><h3>Groupby Operations</h3><span class="tagline">Split-Apply-Combine</span></div><div class="card-body"><p><strong>Aggregation Pipelines:</strong> Partition data into groups, apply custom metric functions, and transform data back into original dimensions.</p><p><strong>Code Snippet:</strong></p><p><code>summary = df.groupby(&#39;region&#39;).agg({&#39;sales&#39;: [&#39;sum&#39;, &#39;mean&#39;], &#39;order_id&#39;: &#39;count&#39;})</code></p></div></div><div class="testing-card ctci-card-4"><div class="card-header"><h3>Merging &amp; Reshaping</h3><span class="tagline">Relational Joins</span></div><div class="card-body"><p><strong>Dataset Integration:</strong> Combine disparate files using database-style joins (`pd.merge`) and reshape layouts using pivot tables for reporting layouts.</p><p><strong>Code Snippet:</strong></p><p><code>merged_df = pd.merge(orders_df, customers_df, on=&#39;customer_id&#39;, how=&#39;inner&#39;)</code></p></div></div></div><hr><h2 id="key-literature-sources" tabindex="-1">Key Literature &amp; Sources <a class="header-anchor" href="#key-literature-sources" aria-label="Permalink to &quot;Key Literature &amp; Sources&quot;">​</a></h2><ul><li><strong>SQL Cookbook (2nd Edition)</strong> by Anthony Molinaro (O&#39;Reilly Media). Covers advanced SQL recipes, window functions, ranking, complex aggregations, string processing, common table expressions (CTEs), and recursive hierarchical queries (Chapters 2, 4, 5, &amp; 9).</li><li><strong>Python for Data Analysis: Data Wrangling with Pandas, NumPy, and Jupyter (3rd Edition)</strong> by Wes McKinney (O&#39;Reilly Media). Covers Pandas data structures, data cleaning, handling missing data, string manipulations, hierarchical indexing, groupby operations, data merging, and exploratory data analysis workflows (Chapters 5, 7, 8, 9, &amp; 10).</li></ul>',22)])])}const u=e(n,[["render",r]]);export{m as __pageData,u as default};
